// next-env.d.ts is generated by `next build`/`next dev` and is gitignored, so a
// fresh checkout (e.g. CI) has no copy of it. Referencing the same type packages
// here makes `tsc --noEmit` work on a clean clone without waiting for a build.
/// <reference types="next" />
/// <reference types="next/image-types/global" />

declare module "*.css" {
  const content: Record<string, string>;
  export default content;
}
